import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry the_entry_name(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 pN,
    .param .u32 pC,
    .param .u32 pH_in,
    .param .u32 pW_in,
    .param .u32 pK_h,
    .param .u32 pStride_h,
    .param .u32 pStride_w,
    .param .u32 pPad_h,
    .param .u32 pPad_w,
    .param .u32 pDil_h,
    .param .u32 pDil_w,
    .param .u32 pH_out,
    .param .u32 pW_out,
    .param .s64 in_sN,
    .param .s64 in_sC,
    .param .s64 in_sH,
    .param .s64 in_sW,
    .param .s64 out_sN,
    .param .s64 out_sC,
    .param .s64 out_sH,
    .param .s64 out_sW,
    .param .s64 w_sO,
    .param .s64 w_sI,
    .param .s64 w_sKH,
    .param .s64 w_sKW
)
{
    .reg .pred p_exit, p_end, p_w_ge0, p_w_lt, p_w_ok, p_h_ge0, p_h_lt, p_h_ok, p_do, p_has_bias;
    .reg .u32 r_tid, r_bid, r_bdim, r_tid_in_block, r_gdim, r_stride;
    .reg .u32 rN, rC, rHin, rWin, rKh, rStrideH_u32, rStrideW_u32, rPadH_u32, rPadW_u32, rDilH_u32, rDilW_u32, rHout, rWout;
    .reg .u32 r_tmp, r_ow, r_oh, r_c, r_n, r_kh;
    .reg .s32 rs_iw, rs_ih_base, rs_ih, rsStrideH, rsStrideW, rsPadH, rsPadW, rsDilH, rsHin_s, rsWin_s, rs_zero;
    .reg .u64 in_ptr, w_ptr, b_ptr, out_ptr;
    .reg .u64 tid64, total64, t64a, t64b, stride64;
    .reg .s64 in_sN64, in_sC64, in_sH64, in_sW64;
    .reg .s64 out_sN64, out_sC64, out_sH64, out_sW64;
    .reg .s64 w_sO64, w_sI64, w_sKH64, w_sKW64;
    .reg .s64 base_in64, base_out64, elem64, tmp64a, tmp64b;
    .reg .s64 w_off64;
    .reg .u64 addr64, w_addr64, b_addr64, off_bytes;
    .reg .f32 f_sum, f_val, f_w, f_b, f_zero;
    // Load pointers
    ld.param.u64 in_ptr,   [input_ptr];
    ld.param.u64 w_ptr,    [weight_ptr];
    ld.param.u64 b_ptr,    [bias_ptr];
    ld.param.u64 out_ptr,  [output_ptr];
    // Load scalars
    ld.param.u32 rN,          [pN];
    ld.param.u32 rC,          [pC];
    ld.param.u32 rHin,        [pH_in];
    ld.param.u32 rWin,        [pW_in];
    ld.param.u32 rKh,         [pK_h];
    ld.param.u32 rStrideH_u32,[pStride_h];
    ld.param.u32 rStrideW_u32,[pStride_w];
    ld.param.u32 rPadH_u32,   [pPad_h];
    ld.param.u32 rPadW_u32,   [pPad_w];
    ld.param.u32 rDilH_u32,   [pDil_h];
    ld.param.u32 rDilW_u32,   [pDil_w];
    ld.param.u32 rHout,       [pH_out];
    ld.param.u32 rWout,       [pW_out];
    // Load strides
    ld.param.s64 in_sN64,   [in_sN];
    ld.param.s64 in_sC64,   [in_sC];
    ld.param.s64 in_sH64,   [in_sH];
    ld.param.s64 in_sW64,   [in_sW];
    ld.param.s64 out_sN64,  [out_sN];
    ld.param.s64 out_sC64,  [out_sC];
    ld.param.s64 out_sH64,  [out_sH];
    ld.param.s64 out_sW64,  [out_sW];
    ld.param.s64 w_sO64,    [w_sO];
    ld.param.s64 w_sI64,    [w_sI];
    ld.param.s64 w_sKH64,   [w_sKH];
    ld.param.s64 w_sKW64,   [w_sKW];
    // Thread id and grid-stride setup
    mov.u32 r_tid_in_block, %tid.x;
    mov.u32 r_bid, %ctaid.x;
    mov.u32 r_bdim, %ntid.x;
    mad.lo.u32 r_tid, r_bid, r_bdim, r_tid_in_block;
    mov.u32 r_gdim, %nctaid.x;
    mul.lo.u32 r_stride, r_gdim, r_bdim;
    // total = N*C*H_out*W_out (u64)
    cvt.u64.u32 total64, rN;
    cvt.u64.u32 t64a, rC;
    mul.lo.u64 total64, total64, t64a;
    cvt.u64.u32 t64a, rHout;
    mul.lo.u64 total64, total64, t64a;
    cvt.u64.u32 t64a, rWout;
    mul.lo.u64 total64, total64, t64a;
    cvt.u64.u32 tid64, r_tid;
    cvt.u64.u32 stride64, r_stride;
LOOP_TID:
    setp.ge.u64 p_exit, tid64, total64;
    @p_exit bra DONE;
    // Decode indices from linear tid
    {
        .reg .u32 r_tid32;
        cvt.u32.u64 r_tid32, tid64;
        mov.u32 r_tmp, r_tid32;
    }
    rem.u32 r_ow, r_tmp, rWout;
    div.u32 r_tmp, r_tmp, rWout;
    rem.u32 r_oh, r_tmp, rHout;
    div.u32 r_tmp, r_tmp, rHout;
    rem.u32 r_c,  r_tmp, rC;
    div.u32 r_n,  r_tmp, rC;
    // Convert needed scalars to s32
    cvt.s32.u32 rsStrideH, rStrideH_u32;
    cvt.s32.u32 rsStrideW, rStrideW_u32;
    cvt.s32.u32 rsPadH,    rPadH_u32;
    cvt.s32.u32 rsPadW,    rPadW_u32;
    cvt.s32.u32 rsDilH,    rDilH_u32;
    cvt.s32.u32 rsHin_s,   rHin;
    cvt.s32.u32 rsWin_s,   rWin;
    // iw = ow*stride_w - pad_w
    cvt.s32.u32 rs_iw, r_ow;
    mul.lo.s32 rs_iw, rs_iw, rsStrideW;
    sub.s32    rs_iw, rs_iw, rsPadW;
    // ih_base = oh*stride_h - pad_h
    cvt.s32.u32 rs_ih_base, r_oh;
    mul.lo.s32 rs_ih_base, rs_ih_base, rsStrideH;
    sub.s32    rs_ih_base, rs_ih_base, rsPadH;
    // Base offsets for input/output (elements)
    // base_in64 = n*in_sN + c*in_sC
    cvt.s64.u32 tmp64a, r_n;
    mul.lo.s64 tmp64a, tmp64a, in_sN64;
    cvt.s64.u32 tmp64b, r_c;
    mul.lo.s64 tmp64b, tmp64b, in_sC64;
    add.s64    base_in64, tmp64a, tmp64b;
    // base_out64 = n*out_sN + c*out_sC
    cvt.s64.u32 tmp64a, r_n;
    mul.lo.s64 tmp64a, tmp64a, out_sN64;
    cvt.s64.u32 tmp64b, r_c;
    mul.lo.s64 tmp64b, tmp64b, out_sC64;
    add.s64    base_out64, tmp64a, tmp64b;
    // Check width validity once (since Kw=1)
    setp.ge.s32 p_w_ge0, rs_iw, 0;
    setp.lt.s32 p_w_lt,  rs_iw, rsWin_s;
    and.pred   p_w_ok, p_w_ge0, p_w_lt;
    // sum = 0.0f
    mov.f32 f_zero, 0f00000000;
    mov.f32 f_sum,  f_zero;
    // Loop over kh
    mov.u32 r_kh, 0;
LOOP_KH:
    setp.ge.u32 p_end, r_kh, rKh;
    @p_end bra LOOP_END;
    // ih = ih_base + kh * dil_h
    {
        .reg .s32 rs_kh;
        cvt.s32.u32 rs_kh, r_kh;
        mul.lo.s32 rs_ih, rs_kh, rsDilH;
        add.s32    rs_ih, rs_ih, rs_ih_base;
    }
    // Check height validity
    setp.ge.s32 p_h_ge0, rs_ih, 0;
    setp.lt.s32 p_h_lt,  rs_ih, rsHin_s;
    and.pred   p_h_ok, p_h_ge0, p_h_lt;
    and.pred   p_do, p_w_ok, p_h_ok;
    @!p_do bra SKIP_ACCUM;
    // Compute input element offset: base_in64 + ih*in_sH + iw*in_sW
    cvt.s64.s32 tmp64a, rs_ih;
    mul.lo.s64 tmp64a, tmp64a, in_sH64;
    add.s64    elem64, base_in64, tmp64a;
    cvt.s64.s32 tmp64b, rs_iw;
    mul.lo.s64 tmp64b, tmp64b, in_sW64;
    add.s64    elem64, elem64, tmp64b;
    // Load input value
    shl.b64    off_bytes, elem64, 2;
    add.u64    addr64, in_ptr, off_bytes;
    ld.global.f32 f_val, [addr64];
    // Compute weight offset: c*w_sO + kh*w_sKH
    cvt.s64.u32 tmp64a, r_c;
    mul.lo.s64 tmp64a, tmp64a, w_sO64;
    cvt.s64.u32 tmp64b, r_kh;
    mul.lo.s64 tmp64b, tmp64b, w_sKH64;
    add.s64    w_off64, tmp64a, tmp64b;
    shl.b64    off_bytes, w_off64, 2;
    add.u64    w_addr64, w_ptr, off_bytes;
    ld.global.f32 f_w, [w_addr64];
    // Accumulate
    fma.rn.f32 f_sum, f_val, f_w, f_sum;
SKIP_ACCUM:
    add.u32 r_kh, r_kh, 1;
    bra LOOP_KH;
LOOP_END:
    // Add bias if provided
    setp.ne.u64 p_has_bias, b_ptr, 0;
    @!p_has_bias bra NO_BIAS;
    {
        .reg .u64 tmpu64;
        cvt.u64.u32 tmpu64, r_c;
        shl.b64     tmpu64, tmpu64, 2;
        add.u64     b_addr64, b_ptr, tmpu64;
        ld.global.f32 f_b, [b_addr64];
        add.f32     f_sum, f_sum, f_b;
    }
NO_BIAS:
    // Store output at base_out64 + oh*out_sH + ow*out_sW
    cvt.s64.u32 tmp64a, r_oh;
    mul.lo.s64 tmp64a, tmp64a, out_sH64;
    add.s64    elem64, base_out64, tmp64a;
    cvt.s64.u32 tmp64b, r_ow;
    mul.lo.s64 tmp64b, tmp64b, out_sW64;
    add.s64    elem64, elem64, tmp64b;
    shl.b64    off_bytes, elem64, 2;
    add.u64    addr64, out_ptr, off_bytes;
    st.global.f32 [addr64], f_sum;
    // Next element in grid-stride loop
    add.u64 tid64, tid64, stride64;
    bra LOOP_TID;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric kernel (kernel_h, 1),
    using a single custom PTX kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        # Parameters: (out_channels=C, in_channels/groups=1, kernel_h=K, kernel_w=1)
        weight = torch.empty(in_channels, 1, kernel_size, 1)
        # Kaiming uniform init as in nn.Conv2d
        init.kaiming_uniform_(weight, a=math.sqrt(5))
        self.weight = nn.Parameter(weight)

        if bias:
            b = torch.empty(in_channels)
            fan_in = kernel_size  # in_channels/groups * K_h * K_w = 1 * K * 1
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            init.uniform_(b, -bound, bound)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "This kernel supports float32 tensors only"
        N, C, H_in, W_in = x.shape
        assert C == self.in_channels, "Channel mismatch"

        K_h = self.kernel_size
        K_w = 1
        stride_h = self.stride
        stride_w = self.stride
        pad_h = self.padding
        pad_w = self.padding
        dil_h = self.dilation
        dil_w = self.dilation

        H_out = (H_in + 2 * pad_h - dil_h * (K_h - 1) - 1) // stride_h + 1
        W_out = (W_in + 2 * pad_w - dil_w * (K_w - 1) - 1) // stride_w + 1

        y = torch.empty((N, C, H_out, W_out), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        # Strides in elements
        in_sN, in_sC, in_sH, in_sW = x.stride()
        out_sN, out_sC, out_sH, out_sW = y.stride()
        w_sO, w_sI, w_sKH, w_sKW = self.weight.stride()

        total = N * C * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block

        bias_arg = self.bias if self.bias is not None else u64(0)

        module.launch(
            "the_entry_name",
            grid=(grid_x, 1, 1),
            block=(block, 1, 1),
            arguments=[
                x, self.weight, bias_arg, y,
                i32(N), i32(C), i32(H_in), i32(W_in),
                i32(K_h), i32(stride_h), i32(stride_w), i32(pad_h), i32(pad_w), i32(dil_h), i32(dil_w),
                i32(H_out), i32(W_out),
                i64(in_sN), i64(in_sC), i64(in_sH), i64(in_sW),
                i64(out_sN), i64(out_sC), i64(out_sH), i64(out_sW),
                i64(w_sO), i64(w_sI), i64(w_sKH), i64(w_sKW),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return y

