import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 pN,
    .param .u32 pC,
    .param .u32 pH_in,
    .param .u32 pW_in,
    .param .u32 pK_h,
    .param .u32 pStride_h,
    .param .u32 pStride_w,
    .param .u32 pPad_h,
    .param .u32 pPad_w,
    .param .u32 pDil_h,
    .param .u32 pDil_w,
    .param .u32 pH_out,
    .param .u32 pW_out,
