    .reg .u32 r_tid, r_bid, r_bdim, r_tid_in_block;
    .reg .u32 rN, rC, rHin, rWin, rKh, rStrideH_u32, rStrideW_u32, rPadH_u32, rPadW_u32, rDilH_u32, rDilW_u32, rHout, rWout;
    .reg .u32 r_tmp, r_ow, r_oh, r_c, r_n, r_kh;
    .reg .s32 rs_iw, rs_ih_base, rs_ih, rsStrideH, rsStrideW, rsPadH, rsPadW, rsDilH, rsHin_s, rsWin_s, rs_zero;
    .reg .u64 in_ptr, w_ptr, b_ptr, out_ptr;
    .reg .u64 tid64, total64, t64a, t64b;
    .reg .s64 in_sN64, in_sC64, in_sH64, in_sW64;
    .reg .s64 out_sN64, out_sC64, out_sH64, out_sW64;
    .reg .s64 w_sO64, w_sI64, w_sKH64, w_sKW64;
    .reg .s64 base_in64, base_out64, elem64, tmp64a, tmp64b;
    .reg .s64 w_off64;
    .reg .u64 addr64, w_addr64, b_addr64, off_bytes;
    .reg .f32 f_sum, f_val, f_w, f_b, f_zero;

    // Load pointers
    ld.param.u64 in_ptr,   [input_ptr];
    ld.param.u64 w_ptr,    [weight_ptr];
    ld.param.u64 b_ptr,    [bias_ptr];
    ld.param.u64 out_ptr,  [output_ptr];

    // Load scalars
    ld.param.u32 rN,          [pN];
    ld.param.u32 rC,          [pC];
    ld.param.u32 rHin,        [pH_in];
    ld.param.u32 rWin,        [pW_in];
    ld.param.u32 rKh,         [pK_h];
    ld.param.u32 rStrideH_u32,[pStride_h];
    ld.param.u32 rStrideW_u32,[pStride_w];
    ld.param.u32 rPadH_u32,   [pPad_h];
    ld.param.u32 rPadW_u32,   [pPad_w];
    ld.param.u32 rDilH_u32,   [pDil_h];
    ld.param.u32 rDilW_u32,   [pDil_w];
    ld.param.u32 rHout,       [pH_out];
    ld.param.u32 rWout,       [pW_out];

    // Load strides
    ld.param.s64 in_sN64,   [in_sN];
    ld.param.s64 in_sC64,   [in_sC];
    ld.param.s64 in_sH64,   [in_sH];
    ld.param.s64 in_sW64,   [in_sW];
    ld.param.s64 out_sN64,  [out_sN];
    ld.param.s64 out_sC64,  [out_sC];
    ld.param.s64 out_sH64,  [out_sH];
    ld.param.s64 out_sW64,  [out_sW];
    ld.param.s64 w_sO64,    [w_sO];
    ld.param.s64 w_sI64,    [w_sI];
    ld.param.s64 w_sKH64,   [w_sKH];
    ld.param.s64 w_sKW64,   [w_sKW];

    // Thread id
    mov.u32 r_tid_in_block, %tid.x;
    mov.u32 r_bid, %ctaid.x;
    mov.u32 r_bdim, %ntid.x;
    mad.lo.u32 r_tid, r_bid, r_bdim, r_tid_in_block;

    // total = N*C*H_out*W_out (u64)
    cvt.u64.u32 total64, rN;
    cvt.u64.u32 t64a, rC;
    mul.lo.u64 total64, total64, t64a;
    cvt.u64.u32 t64a, rHout;
    mul.lo.u64 total64, total64, t64a;
    cvt.u64.u32 t64a, rWout;
    mul.lo.u64 total64, total64, t64a;

    cvt.u64.u32 tid64, r_tid;
    setp.ge.u64 p_exit, tid64, total64;
    @p_exit bra DONE;

    // Decode indices from linear tid
    mov.u32 r_tmp, r_tid;
    rem.u32 r_ow, r_tmp, rWout;
    div.u32 r_tmp, r_tmp, rWout;
    rem.u32 r_oh, r_tmp, rHout;
    div.u32 r_tmp, r_tmp, rHout;
    rem.u32 r_c,  r_tmp, rC;
    div.u32 r_n,  r_tmp, rC;

