.version 8.0
.target sm_89
.address_size 64
.visible .entry the_entry_name(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 pN,
    .param .u32 pC,
    .param .u32 pH_in,
    .param .u32 pW_in,
    .param .u32 pK_h,
    .param .u32 pStride_h,
    .param .u32 pStride_w,
