    .param .s64 in_sC,
    .param .s64 in_sH,
    .param .s64 in_sW,
    .param .s64 out_sN,
    .param .s64 out_sC,
    .param .s64 out_sH,
    .param .s64 out_sW,
    .param .s64 w_sO,
    .param .s64 w_sI,
    .param .s64 w_sKH,
    .param .s64 w_sKW
