    mul.lo.s64 tmp64b, tmp64b, in_sC64;
    add.s64    base_in64, tmp64a, tmp64b;
    // base_out64 = n*out_sN + c*out_sC
    cvt.s64.u32 tmp64a, r_n;
    mul.lo.s64 tmp64a, tmp64a, out_sN64;
    cvt.s64.u32 tmp64b, r_c;
    mul.lo.s64 tmp64b, tmp64b, out_sC64;
    add.s64    base_out64, tmp64a, tmp64b;
