    // Compute weight offset: c*w_sO + kh*w_sKH
    cvt.s64.u32 tmp64a, r_c;
    mul.lo.s64 tmp64a, tmp64a, w_sO64;
    cvt.s64.u32 tmp64b, r_kh;
    mul.lo.s64 tmp64b, tmp64b, w_sKH64;
    add.s64    w_off64, tmp64a, tmp64b;

    shl.b64    off_bytes, w_off64, 2;
    add.u64    w_addr64, w_ptr, off_bytes;
    ld.global.f32 f_w, [w_addr64];

    // Accumulate
    fma.rn.f32 f_sum, f_val, f_w, f_sum;

SKIP_ACCUM:
    add.u32 r_kh, r_kh, 1;
    bra LOOP_KH;

LOOP_END:

    // Add bias if provided
    setp.ne.u64 p_has_bias, b_ptr, 0;
    @!p_has_bias bra NO_BIAS;

    {
        .reg .u64 tmpu64;
        cvt.u64.u32 tmpu64, r_c;
        shl.b64     tmpu64, tmpu64, 2;
        add.u64     b_addr64, b_ptr, tmpu64;
        ld.global.f32 f_b, [b_addr64];
        add.f32     f_sum, f_sum, f_b;
    }

NO_BIAS:
    // Store output at base_out64 + oh*out_sH + ow*out_sW
    cvt.s64.u32 tmp64a, r_oh;
    mul.lo.s64 tmp64a, tmp64a, out_sH64;
    add.s64    elem64, base_out64, tmp64a;
    cvt.s64.u32 tmp64b, r_ow;
    mul.lo.s64 tmp64b, tmp64b, out_sW64;
    add.s64    elem64, elem64, tmp64b;

    shl.b64    off_bytes, elem64, 2;
    add.u64    addr64, out_ptr, off_bytes;
    st.global.f32 [addr64], f_sum;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric kernel (kernel_h, 1),
    using a single custom PTX kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        # Parameters: (out_channels=C, in_channels/groups=1, kernel_h=K, kernel_w=1)
        weight = torch.empty(in_channels, 1, kernel_size, 1)
        # Kaiming uniform init as in nn.Conv2d
        init.kaiming_uniform_(weight, a=math.sqrt(5))
        self.weight = nn.Parameter(weight)

        if bias:
            b = torch.empty(in_channels)
            fan_in = kernel_size  # in_channels/groups * K_h * K_w = 1 * K * 1
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            init.uniform_(b, -bound, bound)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "This kernel supports float32 tensors only"
        N, C, H_in, W_in = x.shape
        assert C == self.in_channels, "Channel mismatch"

        K_h = self.kernel_size
        K_w = 1
        stride_h = self.stride
        stride_w = self.stride
        pad_h = self.padding
        pad_w = self.padding
        dil_h = self.dilation
        dil_w = self.dilation

        H_out = (H_in + 2 * pad_h - dil_h * (K_h - 1) - 1) // stride_h + 1
        W_out = (W_in + 2 * pad_w - dil_w * (K_w - 1) - 1) // stride_w + 1

        y = torch.empty((N, C, H_out, W_out), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        # Strides in elements
        in_sN, in_sC, in_sH, in_sW = x.stride()
        out_sN, out_sC, out_sH, out_sW = y.stride()
        w_sO, w_sI, w_sKH, w_sKW = self.weight.stride()

        total = N * C * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block

        bias_arg = self.bias if self.bias is not None else u64(0)

        module.launch(
            "the_entry_name",
            grid=(grid_x, 1, 1),
            block=(block, 1, 1),
            arguments=[
                x, self.weight, bias_arg, y,
                i32(N), i32(C), i32(H_in), i32(W_in),
                i32(K_h), i32(stride_h), i32(stride_w), i32(pad_h), i32(pad_w), i32(dil_h), i32(dil_w),
                i32(H_out), i32(W_out),
                i64(in_sN), i64(in_sC), i64(in_sH), i64(in_sW),
                i64(out_sN), i64(out_sC), i64(out_sH), i64(out_sW),
                i64(w_sO), i64(w_sI), i64(w_sKH), i64(w_sKW),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return y
